import type { Loop } from '../types'

// An ended loop stays listed this long, so you see it stopped.
export const LOOP_KEEP_MS = 10 * 60 * 1000
const MINUTE = 60_000
const DAY = 24 * 60 * MINUTE

type Field = Set<number>
type Cron = { minute: Field; hour: Field; dom: Field; month: Field; dow: Field; isAnyDom: boolean; isAnyDow: boolean }

function parseField(text: string, min: number, max: number): Field | null {
  const out = new Set<number>()
  for (const part of text.split(',')) {
    const [range = '', stepText] = part.split('/')
    const step = stepText === undefined ? 1 : Number(stepText)
    if (!Number.isInteger(step) || step < 1) return null
    let lo = min
    let hi = max
    if (range !== '*') {
      const [a, b] = range.split('-')
      lo = Number(a)
      hi = b !== undefined ? Number(b) : stepText !== undefined ? max : lo
    }
    if (!Number.isInteger(lo) || !Number.isInteger(hi) || lo < min || hi > max || lo > hi) return null
    for (let v = lo; v <= hi; v += step) out.add(v)
  }
  return out
}

// A five-field cron expression (minute hour day-of-month month day-of-week), local time.
export function parseCron(expr: string): Cron | null {
  const parts = expr.trim().split(/\s+/)
  if (parts.length !== 5) return null
  const [mi = '', ho = '', dm = '', mo = '', dw = ''] = parts
  const minute = parseField(mi, 0, 59)
  const hour = parseField(ho, 0, 23)
  const dom = parseField(dm, 1, 31)
  const month = parseField(mo, 1, 12)
  const dowRaw = parseField(dw, 0, 7)
  if (minute === null || hour === null || dom === null || month === null || dowRaw === null) return null
  // 7 is Sunday too.
  const dow = new Set([...dowRaw].map(d => d % 7))
  return { minute, hour, dom, month, dow, isAnyDom: dm === '*', isAnyDow: dw === '*' }
}

function dayMatches(c: Cron, d: Date): boolean {
  const inDom = c.dom.has(d.getDate())
  const inDow = c.dow.has(d.getDay())
  // As cron reads it: both restricted, either one is enough.
  if (!c.isAnyDom && !c.isAnyDow) return inDom || inDow
  return inDom && inDow
}

// The first minute after `after` the expression matches, within a year; null if never.
export function nextFire(expr: string, after: number): number | null {
  const c = parseCron(expr)
  if (c === null) return null
  const d = new Date(after)
  d.setSeconds(0, 0)
  d.setMinutes(d.getMinutes() + 1)
  const end = after + 366 * DAY
  while (d.getTime() <= end) {
    if (!c.month.has(d.getMonth() + 1)) {
      d.setMonth(d.getMonth() + 1, 1)
      d.setHours(0, 0, 0, 0)
    } else if (!dayMatches(c, d)) {
      d.setDate(d.getDate() + 1)
      d.setHours(0, 0, 0, 0)
    } else if (!c.hour.has(d.getHours())) {
      d.setHours(d.getHours() + 1, 0, 0, 0)
    } else if (!c.minute.has(d.getMinutes())) {
      d.setMinutes(d.getMinutes() + 1, 0, 0)
    } else {
      return d.getTime()
    }
  }
  return null
}

const pad2 = (n: number): string => String(n).padStart(2, '0')

// Words for the common shapes; the expression itself otherwise.
export function humanCron(expr: string): string {
  const parts = expr.trim().split(/\s+/)
  if (parts.length !== 5) return expr
  const [mi = '', ho = '', dm = '', mo = '', dw = ''] = parts
  const isNum = (s: string): boolean => /^\d+$/.test(s)
  const rest = `${dm} ${mo} ${dw}`
  let m = /^\*\/(\d+)$/.exec(mi)
  if (mi === '*' && ho === '*' && rest === '* * *') return 'Every minute'
  if (m !== null && ho === '*' && rest === '* * *') return `Every ${m[1]} minutes`
  m = /^\*\/(\d+)$/.exec(ho)
  if (isNum(mi) && m !== null && rest === '* * *') return `Every ${m[1]} hours`
  if (isNum(mi) && ho === '*' && rest === '* * *') return `Every hour at :${pad2(Number(mi))}`
  if (isNum(mi) && isNum(ho) && rest === '* * *') return `Daily at ${pad2(Number(ho))}:${pad2(Number(mi))}`
  if (isNum(mi) && isNum(ho) && dm === '*' && mo === '*' && dw === '1-5') return `Weekdays at ${pad2(Number(ho))}:${pad2(Number(mi))}`
  return expr
}

type Fields = Record<string, unknown>
const str = (v: unknown): string => (typeof v === 'string' ? v : '')
const num = (v: unknown): number | null => (typeof v === 'number' && Number.isFinite(v) ? v : null)

function blank(over: Partial<Loop> & { id: string; kind: Loop['kind'] }): Loop {
  return {
    schedule: '', every: '', prompt: '', recurring: true, startedAt: null, nextAt: null, lastFiredAt: null, fires: 0,
    delaySeconds: null, reason: '', wakeId: null, endedAt: null, ...over,
  }
}

const isActive = (l: Loop): boolean => l.endedAt === null

// A CronCreate call that went through: a loop with an interval, or a one-shot reminder.
export function addCron(list: readonly Loop[], input: Fields, result: Fields, now: number): Loop[] {
  const id = str(result.id)
  if (id === '') return [...list]
  const schedule = str(input.cron)
  const recurring = result.recurring !== false && input.recurring !== false
  const loop = blank({
    id, kind: 'cron', schedule, prompt: str(input.prompt), recurring, startedAt: now,
    every: recurring ? (str(result.humanSchedule) || humanCron(schedule)) : 'Once',
    nextAt: nextFire(schedule, now),
  })
  return [...list.filter(l => l.id !== id), loop]
}

// A ScheduleWakeup call: a self-paced loop booking its next turn, or ending.
export function addWakeup(list: readonly Loop[], input: Fields, result: Fields, now: number): Loop[] {
  if (input.stop === true || result.stopped === true) {
    return list.map(l => (l.kind === 'wakeup' && isActive(l) ? { ...l, endedAt: now, nextAt: null } : l))
  }
  const prompt = str(input.prompt)
  const delay = num(result.clampedDelaySeconds) ?? num(input.delaySeconds)
  const nextAt = num(result.scheduledFor) ?? (delay === null ? null : now + delay * 1000)
  const prior = list.find(l => l.kind === 'wakeup' && isActive(l) && l.prompt === prompt) ??
    list.find(l => l.kind === 'wakeup' && isActive(l))
  const loop: Loop = prior === undefined
    ? blank({ id: `wake-${now}`, kind: 'wakeup', every: 'Self-paced', prompt, startedAt: now, nextAt, delaySeconds: delay, reason: str(input.reason) })
    : { ...prior, prompt, nextAt, delaySeconds: delay, reason: str(input.reason) || prior.reason }
  return [...list.filter(l => l.id !== loop.id), loop]
}

// A CronDelete that went through, or a stop pressed in the pane.
export function endLoop(list: readonly Loop[], id: string, now: number): Loop[] {
  return list.map(l => ((l.id === id || l.wakeId === id) && isActive(l) ? { ...l, endedAt: now, nextAt: null } : l))
}

// The loop a scheduled prompt belongs to: by its prompt, else the only one due.
export function loopOfFire(list: readonly Loop[], text: string, now: number): Loop | undefined {
  const active = list.filter(isActive)
  const exact = active.find(l => l.prompt.trim() === text.trim())
  if (exact !== undefined) return exact
  const due = active.filter(l => l.nextAt !== null && Math.abs(l.nextAt - now) < 5 * MINUTE)
  if (due.length === 1) return due[0]
  return active.length === 1 ? active[0] : undefined
}

// A loop's prompt just ran: count it and work out the next run.
export function fired(list: readonly Loop[], text: string, now: number): Loop[] {
  const loop = loopOfFire(list, text, now)
  if (loop === undefined) return [...list]
  return list.map(l => {
    if (l.id !== loop.id) return l
    const counted = { ...l, fires: l.fires + 1, lastFiredAt: now }
    if (l.kind === 'wakeup') return { ...counted, nextAt: null, wakeId: null }
    if (!l.recurring) return { ...counted, nextAt: null, endedAt: now }
    return { ...counted, nextAt: nextFire(l.schedule, now) }
  })
}

export type CronSeen = { id: string; schedule: string; recurring: boolean; prompt: string }

// The engine's own list of what will wake this session, at the end of a turn:
// loops it no longer holds have ended; ones made before this mod saw them join.
export function reconcile(list: readonly Loop[], crons: readonly CronSeen[], now: number): Loop[] {
  const ids = new Set(crons.map(c => c.id))
  let next: Loop[] = list.map(l => {
    if (!isActive(l)) return l
    if (l.kind === 'cron') return ids.has(l.id) ? l : { ...l, endedAt: now, nextAt: null }
    const pending = crons.find(c => !c.recurring && (c.id === l.wakeId || c.prompt === l.prompt))
    if (pending === undefined) return { ...l, endedAt: now, nextAt: null }
    return { ...l, wakeId: pending.id, nextAt: l.nextAt ?? nextFire(pending.schedule, now) }
  })
  const known = new Set(next.flatMap(l => [l.id, l.wakeId ?? '']))
  for (const c of crons) {
    if (known.has(c.id)) continue
    next.push(blank({
      id: c.id, kind: 'cron', schedule: c.schedule, prompt: c.prompt, recurring: c.recurring,
      every: c.recurring ? humanCron(c.schedule) : 'Once', nextAt: nextFire(c.schedule, now),
    }))
  }
  next = next.map(l => (isActive(l) && l.kind === 'cron' && (l.nextAt === null || l.nextAt < now - 10 * MINUTE)
    ? { ...l, nextAt: nextFire(l.schedule, now) }
    : l))
  return pruneLoops(next, now)
}

export function pruneLoops(list: readonly Loop[], now: number): Loop[] {
  return list.filter(l => l.endedAt === null || now - l.endedAt < LOOP_KEEP_MS)
}

export function activeLoops(list: readonly Loop[]): Loop[] {
  return list.filter(isActive)
}

files.hooks/map.ts:
// Ringside's model: every Claude session on this computer and what each one
// started, drawn from this session's own state, the other sessions' board files and
// the session list (the engine's registry, or the sessions mod). Pure: no `$` here, so it is tested on its own.

import type { Ask, FleetFile, Job, Loop, MapNode, NeedKind, NodeKind, NodeStatus, Progress } from '../types'

export type { FleetFile, MapNode, NodeKind, NodeStatus, Progress }
export type SessionStatus = 'running' | 'waiting' | 'stuck' | 'idle'

export type MapSession = {
  sessionId: string
  name: string
  branch: string
  cwd: string
  isSelf: boolean
  // It runs this mod, so it publishes what it started; else only the session list's word.
  hasMap: boolean
  status: SessionStatus
  doing: string
  why: string
  since: number
  contextPercent: number | null
  costUsd: number | null
  nodes: MapNode[]
  // What it waits on the person for, and the choices it offered (from its board file).
  needKind?: NeedKind
  asks?: Ask[]
}

export type MapNeed = {
  sessionId: string
  nodeId: string | null
  where: string
  why: string
  since: number
  kind: 'wait' | 'stuck'
  isSelf: boolean
  // Only the question its answer ended on: the pane lists it, the band leaves it out.
  isReply?: boolean
  asks?: Ask[]
}

type Fields = Record<string, unknown>
const str = (v: unknown): string => (typeof v === 'string' ? v : '')
const numOr = (v: unknown, or: number | null): number | null => (typeof v === 'number' && Number.isFinite(v) ? v : or)
const oneLine = (s: string): string => s.replace(/\s+/g, ' ').trim()

/* ---------- terminal cells ---------- */

// Terminal cells a character takes: two for CJK, fullwidth forms and emoji, one otherwise.
function cellsOf(ch: string): number {
  const c = ch.codePointAt(0) ?? 0
  const isWide = (c >= 0x1100 && c <= 0x115f) || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) ||
    (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) ||
    (c >= 0xffe0 && c <= 0xffe6) || (c >= 0x1f300 && c <= 0x1faff) || (c >= 0x20000 && c <= 0x3fffd)
  return isWide ? 2 : 1
}

export function cellWidth(s: string): number {
  let n = 0
  for (const ch of s) n += cellsOf(ch)
  return n
}

// Cut to n terminal cells, an ellipsis marking the cut.
export function fit(s: string, n: number): string {
  const t = oneLine(s)
  if (n <= 0) return ''
  if (cellWidth(t) <= n) return t
  let out = ''
  let used = 0
  for (const ch of t) {
    if (used + cellsOf(ch) > n - 1) break
    out += ch
    used += cellsOf(ch)
  }
  return `${out}…`
}

// Up to maxLines lines of n cells, broken at spaces where it can; the last one cut with an ellipsis.
export function wrap(s: string, n: number, maxLines: number): string[] {
  let rest = oneLine(s)
  const out: string[] = []
  if (n <= 0) return out
  while (rest !== '' && out.length < maxLines) {
    if (cellWidth(rest) <= n) {
      out.push(rest)
      break
    }
    if (out.length === maxLines - 1) {
      out.push(fit(rest, n))
      break
    }
    let take = ''
    let used = 0
    for (const ch of rest) {
      if (used + cellsOf(ch) > n) break
      take += ch
      used += cellsOf(ch)
    }
    const space = take.lastIndexOf(' ')
    const cut = space > n / 3 ? take.slice(0, space) : take
    out.push(cut.trimEnd())
    rest = rest.slice(cut.length).trimStart()
  }
  return out
}

// How long, for a clock beside a row: 0:42 and 12:05 under an hour, then 1h05m, then 2d.
export function dur(ms: number): string {
  if (ms < 60 * 60_000) {
    const s = Math.max(0, Math.floor(ms / 1000))
    return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
  }
  return span(ms)
}

// A span in words: 45s, 12m, 1h05m, 2d.
export function span(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.round(s / 60)
  if (m < 60) return `${m}m`
  const h = Math.floor(m / 60)
  if (h < 48) return `${h}h${String(m % 60).padStart(2, '0')}m`
  return `${Math.floor(h / 24)}d`
}

/* ---------- plain words ---------- */

const TEST_RE = /\b(test|tests|vitest|jest|pytest|playwright|mocha|rspec|phpunit)\b/i
const LINT_RE = /\b(lint|eslint|prettier|ruff|clippy|stylelint)\b/i
const TYPECHECK_RE = /\b(tsc|mypy|pyright|type-?check)\b/i
const BUILD_RE = /\b(build|compile|webpack|esbuild|make)\b/i
const INSTALL_RE = /\b(npm (i|install|ci)|pnpm (i|install|add)|yarn( add| install)?|bun (i|install|add)|pip3? install|brew install|cargo add)\b/i

const READ_CMDS = new Set(['cat', 'head', 'tail', 'less', 'more', 'bat', 'nl', 'wc'])
const SEARCH_CMDS = new Set(['grep', 'egrep', 'rg', 'ag', 'ack'])
const LIST_CMDS = new Set(['ls', 'find', 'fd', 'tree'])

// A shell command that only looks at the code, by its first command: "reading pricing.ts",
// "searching the code", "listing files". Anything else is null.
export function lookStep(command: string): string | null {
  // The first real command: past a `cd` and a loop's head (`cd src && for f in a b; do cat $f; done`).
  const parts = command.split(/\s*(?:&&|\|\||;|\|)\s*/).map(p => p.replace(/^(do|then)\s+/, ''))
  const first = parts.find(p => !/^(for|while|if|until|cd|pushd)\s/.test(p)) ?? ''
  const [cmd = '', ...args] = first.trim().split(/\s+/)
  const name = cmd.split('/').pop() ?? cmd
  if (name === 'git' && args[0] === 'ls-files') return 'listing files'
  if (name === 'git' && (args[0] === 'grep' || args[0] === 'log' && args.includes('-S'))) return 'searching the code'
  if (LIST_CMDS.has(name)) return 'listing files'
  if (SEARCH_CMDS.has(name)) return 'searching the code'
  if (READ_CMDS.has(name) || (name === 'sed' && args.includes('-n'))) {
    // Not an option, a line range, a quoted script or a shell variable.
    const file = args.filter(a => !a.startsWith('-') && !/^\d+(,\d+)?p?$/.test(a) && !a.startsWith("'") && !a.replace(/"/g, '').startsWith('$')).pop()
    return file === undefined ? 'reading files' : `reading ${file.replace(/["']/g, '').split('/').pop() ?? file}`
  }
  return null
}

// What a call is doing, the way a person would say it.
export function plainStep(tool: string, detail: string): string {
  const d = oneLine(detail)
  switch (tool) {
    case 'Read':
      return d === '' ? 'reading a file' : `reading ${d}`
    case 'Grep':
    case 'Glob':
      return d === '' ? 'searching the code' : `searching for ${d}`
    case 'Edit':
    case 'Write':
    case 'MultiEdit':
    case 'NotebookEdit':
      return d === '' ? 'editing a file' : `editing ${d}`
    case 'Bash': {
      const isBackground = d.endsWith('(background)')
      const core = d.replace(/\s*\(background\)$/, '')
      // Looking at the code first: `grep -rn "test" src` searches, it does not run tests.
      const what = lookStep(core) ?? (TEST_RE.test(core) ? 'running tests'
        : LINT_RE.test(core) ? 'checking style'
          : TYPECHECK_RE.test(core) ? 'type-checking'
            : INSTALL_RE.test(core) ? 'installing packages'
              : BUILD_RE.test(core) ? 'building'
                : /^git\s/.test(core) ? `git ${core.replace(/^git\s+/, '')}`
                  : core === '' ? 'running a command'
                    // A description the model wrote ("Rebuild the site") reads as it is; a bare command gets "running".
                    : /^[A-Z][a-z]+\s/.test(core) ? `${core.charAt(0).toLowerCase()}${core.slice(1)}`
                      : `running ${core}`)
      return isBackground ? `${what} in the background` : what
    }
    case 'WebFetch':
      return `reading ${d.split('/')[0] || 'a web page'}`
    case 'WebSearch':
      return d === '' ? 'searching the web' : `searching the web for ${d}`
    case 'Agent':
      return d === '' ? 'starting an agent' : `starting ${d}`
    case 'Skill':
      return d === '' ? 'using a skill' : `using /${d}`
    case 'AskUserQuestion':
      return 'asking you a question'
    case 'ExitPlanMode':
      return 'waiting for you to approve a plan'
    case 'SendMessage':
      return 'messaging a teammate'
    case 'SubagentHandback':
      return 'handing back its answer'
    case 'TaskOutput':
      return 'reading a background task'
    case 'TaskCreate':
    case 'TaskUpdate':
    case 'TaskList':
    case 'TaskGet':
    case 'TodoWrite':
      return 'updating its task list'
    default:
      // savvy-progress's own report tool: the bar already says it.
      if (tool === 'step' && d === 'savvy-progress') return 'reporting progress'
      return d === '' ? tool : `${tool} (${d})`
  }
}

/* ---------- stuck ---------- */

// Working with no new step this long: maybe stuck (a long think stays under it).
export const STUCK_QUIET_MS = 10 * 60_000
// One foreground step running this long: maybe stuck.
export const STUCK_STEP_MS = 20 * 60_000
export const REPEAT_FAILS = 3

type Step = Pick<Job, 'tool' | 'detail' | 'startedAt' | 'endedAt' | 'isError' | 'taskId' | 'need'>

// A tool by what it does, for a stuck reason in plain words.
const STEP_WORD: Record<string, string> = {
  Bash: 'command', Read: 'file read', Grep: 'search', Glob: 'search', Edit: 'edit', Write: 'edit', MultiEdit: 'edit',
  NotebookEdit: 'edit', WebFetch: 'page fetch', WebSearch: 'web search', Skill: 'skill', Agent: 'agent start',
}

// Why one worker (the main loop or a subagent) may be stuck, from its own calls in order; '' when it looks fine.
export function stuckReason(steps: readonly Step[], isWorking: boolean, now: number): string {
  if (!isWorking) return ''
  const ended = steps.filter(s => s.endedAt !== null)
  const last = ended[ended.length - 1]
  if (last !== undefined && last.isError) {
    let n = 0
    for (let i = ended.length - 1; i >= 0; i--) {
      const s = ended[i]
      if (s === undefined || !s.isError || s.tool !== last.tool || s.detail !== last.detail) break
      n += 1
    }
    if (n >= REPEAT_FAILS) return `the same ${STEP_WORD[last.tool] ?? 'step'} failed ${n} times in a row: ${last.detail}`
  }
  // Background shells, waits on the person and subagents run long on purpose.
  const live = steps.filter(s => s.endedAt === null && s.taskId === null && s.need === null && s.tool !== 'Agent')
  const oldest = live.reduce<Step | null>((a, s) => (a === null || s.startedAt < a.startedAt ? s : a), null)
  if (oldest !== null) {
    return now - oldest.startedAt > STUCK_STEP_MS ? `one step has run for ${span(now - oldest.startedAt)}: ${plainStep(oldest.tool, oldest.detail)}` : ''
  }
  if (steps.some(s => s.endedAt === null)) return ''
  const lastAt = steps.reduce((a, s) => Math.max(a, s.endedAt ?? s.startedAt), 0)
  if (lastAt > 0 && now - lastAt > STUCK_QUIET_MS) return `no new step for ${span(now - lastAt)}`
  return ''
}

/* ---------- other mods' state, read only if it has the shape we know ---------- */

export type SavvyRun = { agentId: string; description: string; done: number | null; total: number | null; note: string; costUsd: number | null }

// savvy-progress's `agents`: each worker's own step reports and an estimated cost.
export function adaptSavvy(raw: unknown): SavvyRun[] {
  if (!Array.isArray(raw)) return []
  return raw.flatMap(v => {
    if (v === null || typeof v !== 'object') return []
    const o = v as Fields
    const agentId = str(o.agentId) || str(o.id)
    const description = str(o.description)
    if (agentId === '' && description === '') return []
    return [{ agentId, description, done: numOr(o.stepDone, null), total: numOr(o.stepTotal, null), note: str(o.stepNote), costUsd: numOr(o.costUsd, null) }]
  })
}

export type FlightRun = { id: string; tokens: number | null }
export type FlightLoop = { id: string; steps: number; firstAt: number; lastAt: number; isDone: boolean }

// flightdeck's `agents`: each subagent's live context size.
export function adaptFlightAgents(raw: unknown): FlightRun[] {
  if (!Array.isArray(raw)) return []
  return raw.flatMap(v => {
    if (v === null || typeof v !== 'object') return []
    const o = v as Fields
    const id = str(o.id)
    return id === '' ? [] : [{ id, tokens: numOr(o.ctx, null) }]
  })
}

// flightdeck's `loops`: model loops no subagent card claims, workflow agents among them.
export function adaptFlightLoops(raw: unknown): FlightLoop[] {
  if (!Array.isArray(raw)) return []
  return raw.flatMap(v => {
    if (v === null || typeof v !== 'object') return []
    const o = v as Fields
    const id = str(o.id)
    const firstAt = numOr(o.firstAt, null)
    const lastAt = numOr(o.lastAt, null)
    if (id === '' || firstAt === null || lastAt === null) return []
    return [{ id, steps: numOr(o.steps, 0) ?? 0, firstAt, lastAt, isDone: o.isDone === true }]
  })
}

/* ---------- this session's nodes ---------- */

export type AgentLike = {
  id: string
  type: string
  purpose: string
  status: string
  isLive: boolean
  from: number
  to: number | null
  step: string
  result: string
}

const AGENT_STATUS: Record<string, NodeStatus> = {
  running: 'running', pending: 'running', waiting: 'waiting', idle: 'idle',
  completed: 'done', ended: 'done', failed: 'failed', killed: 'failed',
}

export type SelfInput = {
  agents: readonly AgentLike[]
  jobs: readonly Job[]
  loops: readonly Loop[]
  savvy: readonly SavvyRun[]
  flightAgents: readonly FlightRun[]
  flightLoops: readonly FlightLoop[]
  now: number
}

// What this session started: its subagents, background shells, loops and workflow agents.
export function selfNodes(input: SelfInput): MapNode[] {
  const { now } = input
  const nodes: MapNode[] = []
  const savvyOf = (a: AgentLike): SavvyRun | undefined =>
    input.savvy.find(r => r.agentId !== '' && r.agentId === a.id) ?? input.savvy.find(r => r.agentId === '' && r.description !== '' && r.description === a.purpose)
  for (const a of input.agents) {
    const own = input.jobs.filter(j => j.agentId === a.id)
    const live = own.filter(j => j.endedAt === null)
    const current = live[live.length - 1] ?? own[own.length - 1]
    const baseStatus = AGENT_STATUS[a.status] ?? (a.isLive ? 'running' : 'done')
    const stuck = baseStatus === 'running' ? stuckReason(own, true, now) : ''
    const waitJob = live.find(j => j.need !== null)
    const status: NodeStatus = waitJob !== undefined ? 'waiting' : stuck !== '' ? 'stuck' : baseStatus
    const s = savvyOf(a)
    const f = input.flightAgents.find(r => r.id === a.id)
    const now0 = current === undefined ? (a.step === '' ? '' : a.step) : plainStep(current.tool, current.detail)
    nodes.push({
      id: a.id,
      kind: 'agent',
      title: `${a.type} · ${a.purpose || 'subagent'}`,
      status,
      now: status === 'idle' ? 'waiting for its next task' : status === 'done' ? 'finished' : status === 'failed' ? 'failed' : now0,
      raw: current === undefined ? a.step : `${current.tool} ${current.detail}`,
      why: waitJob?.need?.text ?? (status === 'waiting' ? 'waiting for you' : stuck !== '' ? stuck : a.result),
      from: a.from,
      to: a.to,
      progress: s !== undefined && s.total !== null && s.total > 0 ? { done: Math.min(s.done ?? 0, s.total), total: s.total, note: s.note } : null,
      costUsd: s?.costUsd ?? null,
      tokens: f?.tokens ?? null,
    })
  }
  for (const j of input.jobs) {
    if (j.taskId === null || j.endedAt !== null || j.agentId !== null) continue
    const command = j.detail.replace(/\s*\(background\)$/, '')
    nodes.push({
      id: `job:${j.id}`, kind: 'job', title: `shell · ${command}`, status: 'running',
      now: plainStep(j.tool, j.detail), raw: `${j.tool} ${j.detail}`, why: '', from: j.startedAt, to: null,
      progress: null, costUsd: null, tokens: null,
    })
  }
  for (const l of input.loops) {
    if (l.endedAt !== null) continue
    const next = l.nextAt === null ? 'no next run booked' : l.nextAt <= now ? 'due now' : `next run in ${span(l.nextAt - now)}`
    nodes.push({
      id: `loop:${l.id}`, kind: 'loop', title: `loop · ${l.every || 'repeats'}`, status: 'idle',
      now: next, raw: l.prompt, why: l.prompt, from: l.startedAt ?? now, to: null, progress: null, costUsd: null, tokens: null,
    })
  }
  for (const w of input.flightLoops) {
    if (w.isDone || now - w.lastAt > 10 * 60_000) continue
    nodes.push({
      id: `workflow:${w.id}`, kind: 'workflow', title: 'workflow agent', status: 'running',
      now: `${w.steps} model step${w.steps === 1 ? '' : 's'} so far`, raw: '', why: 'seen by flightdeck', from: w.firstAt, to: null,
      progress: null, costUsd: null, tokens: null,
    })
  }
  return nodes
}

/* ---------- every session ---------- */

// A session list row, as far as the map needs.
export type RowLike = {
  sessionId: string
  name: string
  cwd: string
  group: 'needs' | 'working' | 'idle'
  state: string
  since: number
  summary: string
  isSelf: boolean
  usage: { contextPercent: number | null; costUsd: number | null } | null
}

// A session list's "Tool: detail" line (what a session last did) in plain words; anything else as it is.
const TOOL_LINE = /^(Bash|Read|Edit|Write|MultiEdit|NotebookEdit|Grep|Glob|Agent|WebFetch|WebSearch|Skill|TaskCreate|TaskUpdate|TaskList|TaskGet|TodoWrite|TaskOutput)(?::\s+(.*))?$/
export function plainSummary(summary: string): string {
  const m = TOOL_LINE.exec(summary.trim())
  return m === null ? summary : plainStep(m[1] ?? '', m[2] ?? '')
}

// The engine's word for a session's state, in plain words.
const STATE_WORDS: Record<string, string> = { busy: 'working', working: 'working', waiting: 'waiting for you', blocked: 'blocked', idle: 'idle', done: 'finished', failed: 'failed', stopped: 'stopped' }
export function stateWord(state: string): string {
  return STATE_WORDS[state] ?? state
}

const NODE_KINDS = new Set<NodeKind>(['agent', 'job', 'loop', 'workflow'])
const NODE_STATUSES = new Set<NodeStatus>(['running', 'waiting', 'stuck', 'idle', 'done', 'failed'])

// A node as read off another session's file, shaped or refused.
export function asMapNode(v: unknown): MapNode | null {
  if (v === null || typeof v !== 'object') return null
  const o = v as Fields
  const id = str(o.id)
  const kind = o.kind as NodeKind
  const status = o.status as NodeStatus
  if (id === '' || !NODE_KINDS.has(kind) || !NODE_STATUSES.has(status)) return null
  const p = o.progress as Fields | null
  const total = p !== null && typeof p === 'object' ? numOr(p.total, null) : null
  return {
    id, kind, status,
    title: str(o.title), now: str(o.now), raw: str(o.raw), why: str(o.why),
    from: numOr(o.from, 0) ?? 0, to: numOr(o.to, null),
    progress: total !== null && total > 0 && p !== null ? { done: numOr(p.done, 0) ?? 0, total, note: str(p.note) } : null,
    costUsd: numOr(o.costUsd, null), tokens: numOr(o.tokens, null),
  }
}

export type SelfSession = {
  sessionId: string
  name: string
  cwd: string
  branch: string
  status: SessionStatus
  doing: string
  why: string
  since: number
  nodes: MapNode[]
}

const RANK: Record<SessionStatus, number> = { waiting: 0, stuck: 1, running: 2, idle: 3 }
const base = (p: string): string => p.split('/').filter(Boolean).pop() ?? p

// The whole map: this session first, then the rest by what they ask of the person, then by name.
// Files are trusted for sessions that run this mod; the session list fills in the rest.
// A wait the session list has seen for longer than `freshMs` is old news (a dead background job): idle here.
export function buildMap(self: SelfSession, files: readonly FleetFile[], rows: readonly RowLike[], hidden: readonly string[], now: number, staleMs: number, freshMs = 24 * 60 * 60 * 1000): MapSession[] {
  const skip = new Set(hidden)
  const rowOf = new Map(rows.map(r => [r.sessionId, r]))
  const selfRow = rowOf.get(self.sessionId) ?? rows.find(r => r.isSelf)
  const out: MapSession[] = [{
    sessionId: self.sessionId, name: self.name, branch: self.branch, cwd: self.cwd, isSelf: true, hasMap: true,
    status: self.status, doing: self.doing, why: self.why, since: self.since,
    contextPercent: selfRow?.usage?.contextPercent ?? null, costUsd: selfRow?.usage?.costUsd ?? null, nodes: self.nodes,
  }]
  const seen = new Set([self.sessionId])
  const others: MapSession[] = []
  for (const f of files) {
    if (seen.has(f.sessionId) || skip.has(f.sessionId) || now - f.heartbeatAt > staleMs) continue
    seen.add(f.sessionId)
    const r = rowOf.get(f.sessionId)
    const status: SessionStatus = f.state === 'needs' ? 'waiting' : f.stuck !== '' ? 'stuck' : f.state === 'working' ? 'running' : 'idle'
    others.push({
      sessionId: f.sessionId, name: r?.name || f.name || base(f.cwd), branch: f.branch, cwd: f.cwd, isSelf: false, hasMap: true,
      status, doing: f.doing, why: status === 'waiting' ? f.doing : status === 'stuck' ? f.stuck : '', since: r?.since ?? f.heartbeatAt,
      contextPercent: r?.usage?.contextPercent ?? null, costUsd: r?.usage?.costUsd ?? null, nodes: f.nodes,
      ...(status === 'waiting' && f.needKind !== undefined ? { needKind: f.needKind } : {}),
      ...(status === 'waiting' && f.asks !== undefined && f.asks.length > 0 ? { asks: f.asks } : {}),
    })
  }
  for (const r of rows) {
    if (seen.has(r.sessionId) || skip.has(r.sessionId) || r.isSelf) continue
    seen.add(r.sessionId)
    const isOld = r.group === 'needs' && now - r.since > freshMs
    const status: SessionStatus = r.group === 'needs' && !isOld ? 'waiting' : r.group === 'working' ? 'running' : 'idle'
    others.push({
      sessionId: r.sessionId, name: r.name || base(r.cwd), branch: '', cwd: r.cwd, isSelf: false, hasMap: false,
      status, doing: isOld ? `${plainSummary(r.summary) || stateWord(r.state)} (old)` : plainSummary(r.summary) || stateWord(r.state), why: status === 'waiting' ? (plainSummary(r.summary) || stateWord(r.state)) : '', since: r.since,
      contextPercent: r.usage?.contextPercent ?? null, costUsd: r.usage?.costUsd ?? null, nodes: [],
    })
  }
  others.sort((a, b) => RANK[a.status] - RANK[b.status] || a.name.localeCompare(b.name))
  return [...out, ...others]
}

// Everything that needs the person, across the map: waits first, then what may be stuck; oldest first.
export function needsOf(map: readonly MapSession[]): MapNeed[] {
  const list: MapNeed[] = []
  for (const s of map) {
    if (s.status === 'waiting' || s.status === 'stuck') {
      list.push({
        sessionId: s.sessionId, nodeId: null, where: s.isSelf ? 'this session' : s.name, why: s.why || s.doing, since: s.since, kind: s.status === 'waiting' ? 'wait' : 'stuck', isSelf: s.isSelf,
        ...(s.status === 'waiting' && s.needKind === 'reply' ? { isReply: true } : {}),
        ...(s.status === 'waiting' && s.asks !== undefined ? { asks: s.asks } : {}),
      })
    }
    for (const n of s.nodes) {
      if (n.status !== 'waiting' && n.status !== 'stuck') continue
      list.push({ sessionId: s.sessionId, nodeId: n.id, where: `${s.isSelf ? '' : `${s.name} › `}${n.title.split(' · ')[0] ?? n.title}`, why: n.why || n.now, since: n.from, kind: n.status === 'waiting' ? 'wait' : 'stuck', isSelf: s.isSelf })
    }
  }
  return list.sort((a, b) => (a.kind === b.kind ? a.since - b.since : a.kind === 'wait' ? -1 : 1))
}

export type Zoom = 'cards' | 'lines' | 'dots'

// The densest view that still fits: a card is about three rows, a line one, a session of dots one.
export function autoZoom(map: readonly MapSession[], needs: number, rows: number): Zoom {
  const nodes = map.reduce((n, s) => n + s.nodes.length, 0)
  const head = 8 + Math.min(needs, 6)
  if (head + (map.length + nodes) * 3 <= rows) return 'cards'
  if (head + map.length + nodes <= rows) return 'lines'
  return 'dots'
}

/* ---------- the desktop's drawing ---------- */

const esc = (s: string): string => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const STROKE: Record<NodeStatus, string> = { running: '#4a8fd6', waiting: '#c99a16', stuck: '#d47a2a', idle: '#9aa5b1', done: '#4f9a66', failed: '#c0473b' }
const MARK: Record<NodeStatus, string> = { running: '●', waiting: '!', stuck: '?', idle: '○', done: '✓', failed: '✗' }

// Sessions left, what each started right, joined by curves: one picture of the whole map.
// A self-contained card look (its own fills) so it reads on a light or a dark desktop.
// `maxWidth` is the pane's width in CSS pixels; the drawing takes it (within 380 to 760) so labels get the room there is.
// `show` passes each label through before it is cut to width: recording mode's mask.
export function graphSvg(map: readonly MapSession[], now: number, maxWidth = 434, show: (text: string) => string = t => t): { source: string; height: number; width: number } {
  const ROW = 54
  const GAP = 44
  const W = Math.max(380, Math.min(760, Math.round(maxWidth)))
  const SW = Math.round((W - GAP - 4) * 0.4)
  const CW = W - GAP - 4 - SW
  const PX = 7 // a terminal cell's worth of a 12px label, a little generous so labels never run into the clock
  const parts: string[] = []
  const wires: string[] = []
  let y = 4
  const box = (x: number, top: number, w: number, h: number, status: NodeStatus, line1: string, line2: string, clock: string, isSelf: boolean, progress: Progress | null): string => {
    const clockCells = clock === '' ? 0 : cellWidth(clock) + 1
    const room = Math.floor((w - 22) / PX)
    const t1 = fit(`${MARK[status]} ${show(line1)}`, room - clockCells)
    const t2 = fit(show(line2), room)
    const fill = status === 'waiting' ? '#fff7dd' : isSelf ? '#eef4fb' : '#ffffff'
    let bar = ''
    if (progress !== null) {
      const bw = w - 24
      const fw = Math.round((bw * progress.done) / progress.total)
      // Below the second line's descenders, inside the box: the box is taller when it has a bar.
      bar = `<rect x="${x + 12}" y="${top + h - 7}" width="${bw}" height="3" rx="1.5" fill="#e3e7ec"/><rect x="${x + 12}" y="${top + h - 7}" width="${fw}" height="3" rx="1.5" fill="#9b59b6"/>`
    }
    return `<rect x="${x}" y="${top}" width="${w}" height="${h}" rx="9" fill="${fill}" stroke="${STROKE[status]}" stroke-width="${status === 'waiting' || status === 'stuck' ? 2 : 1.2}"/>` +
      `<text x="${x + 10}" y="${top + 17}" font-family="-apple-system, Segoe UI, sans-serif" font-size="12" font-weight="600" fill="#1d2329">${esc(t1)}</text>` +
      (clock === '' ? '' : `<text x="${x + w - 9}" y="${top + 17}" text-anchor="end" font-family="-apple-system, Segoe UI, sans-serif" font-size="11" fill="#5b6670">${esc(clock)}</text>`) +
      `<text x="${x + 10}" y="${top + 32}" font-family="-apple-system, Segoe UI, sans-serif" font-size="11" fill="#5b6670">${esc(t2)}</text>` + bar
  }
  for (const s of map) {
    const block = Math.max(1, s.nodes.length) * ROW
    const sy = y + block / 2 - 21
    const sClock = span(now - s.since)
    parts.push(box(2, sy, SW, 42, s.status, s.isSelf ? `${s.name} (here)` : s.name, s.why || s.doing || s.branch, sClock, s.isSelf, null))
    s.nodes.forEach((n, j) => {
      const cy = y + j * ROW + 4
      wires.push(`<path d="M${2 + SW},${sy + 21} C${SW + 24},${sy + 21} ${SW + GAP - 20},${cy + 20} ${SW + GAP},${cy + 20}" fill="none" stroke="${n.status === 'running' ? '#4a8fd6' : '#b4bcc6'}" stroke-width="1.5"${n.status === 'running' ? ' stroke-dasharray="4 3"' : ''}/>`)
      parts.push(box(SW + GAP, cy, CW, n.progress === null ? 40 : 46, n.status, n.title, n.status === 'waiting' || n.status === 'stuck' ? n.why : n.now, n.to !== null ? '' : n.kind === 'loop' ? '' : span(now - n.from), false, n.progress))
    })
    y += block + 12
  }
  const height = Math.max(y, 60)
  return { source: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${height}" width="${W}" height="${height}">${wires.join('')}${parts.join('')}</svg>`, height, width: W }
}

files.hooks/mask.ts:
// Masks personal details for display while a screen is being recorded:
// set CLAUDE_MODS_RECORDING=1 (and optionally CLAUDE_MODS_RECORDING_TERMS, a
// JSON array of extra words to hide) in the session's environment.

type Rule = [RegExp, string | ((match: string, ...groups: string[]) => string)]

function luhn(digits: string): boolean {
  let sum = 0
  for (let i = 0; i < digits.length; i += 1) {
    let d = Number(digits[digits.length - 1 - i])
    if (i % 2 === 1) {
      d *= 2
      if (d > 9) d -= 9
    }
    sum += d
  }
  return sum % 10 === 0
}

const RULES: Rule[] = [
  [/-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g, '[private key]'],
  [/\b(?:sk|pk|rk)[-_](?:live|test|ant|proj)[-_][A-Za-z0-9_-]{12,}/g, '[secret]'],
  [/\bsk-[A-Za-z0-9_-]{20,}/g, '[secret]'],
  [/\bgh[pousr]_[A-Za-z0-9]{20,}\b/g, '[secret]'],
  [/\bgithub_pat_[A-Za-z0-9_]{20,}\b/g, '[secret]'],
  [/\bxox[abprs]-[A-Za-z0-9-]{10,}/g, '[secret]'],
  [/\bAKIA[0-9A-Z]{16}\b/g, '[secret]'],
  [/\bAIza[0-9A-Za-z_-]{35}\b/g, '[secret]'],
  [/\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}/g, '[secret]'],
  [/(\bBearer\s+)[A-Za-z0-9._~+/=-]{16,}/g, (_m, lead) => `${lead}[secret]`],
  [/((?:api[_-]?key|secret|token|password|passwd|pwd)["']?\s*[:=]\s*["']?)[^\s"',;]{6,}/gi, (_m, lead) => `${lead}[secret]`],
  [/[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g, '[email]'],
  [/\b\d(?:[ -]?\d){12,18}\b/g, m => {
    const digits = m.replace(/\D/g, '')
    return /^[3-6]/.test(digits) && luhn(digits) ? '[card]' : m
  }],
  [/(?:US\$|HK\$|NT\$|A\$|C\$|S\$|\$|€|£|¥|₩|₹)\s?\d[\d,]*(?:\.\d+)?(?:\s?(?:[kKmM]|bn)\b)?/g, '[amount]'],
  [/\b\d[\d,]*(?:\.\d+)?\s?(?:USD|HKD|EUR|GBP|JPY|CNY|RMB|AUD|CAD|SGD|TWD)\b/g, '[amount]'],
  [/\+\d{1,3}[\s.-]?\d{1,4}(?:[\s.-]?\d{2,4}){2,4}\b/g, '[phone]'],
  [/\(\d{3}\)\s?\d{3}[-.\s]\d{4}\b/g, '[phone]'],
  [/\b(?!127\.0\.0\.1\b)(?!0\.0\.0\.0\b)(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b/g, '[ip]'],
  [/\/Users\/[^/\s'"]+/g, '/Users/[user]'],
  [/\/home\/[^/\s'"]+/g, '/home/[user]'],
]

const escape = (s: string): string => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

export function mask(text: string, extra: readonly string[] = []): string {
  let out = text
  for (const [pattern, replacement] of RULES) {
    out = typeof replacement === 'string'
      ? out.replace(pattern, replacement)
      : out.replace(pattern, replacement as (m: string, ...g: string[]) => string)
  }
  for (const term of extra) {
    if (term.trim() !== '') out = out.replace(new RegExp(escape(term.trim()), 'gi'), '[hidden]')
  }
  return out
}

export function maskDeep(value: unknown, extra: readonly string[] = []): unknown {
  if (typeof value === 'string') return mask(value, extra)
  if (Array.isArray(value)) return value.map(v => maskDeep(v, extra))
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([k, v]) => [k, maskDeep(v, extra)]))
  }
  return value
}

// The extra words `/recording hide` adds, as recording-mode publishes them in
// CLAUDE_MODS_RECORDING_TERMS (a JSON array), so every mod hides them too.
export function recordingTerms(raw: string | undefined): string[] {
  if (raw === undefined || raw === '') return []
  try {
    const v = JSON.parse(raw) as unknown
    return Array.isArray(v) ? v.filter((t): t is string => typeof t === 'string') : []
  } catch {
    return []
  }
}

files.types/index.d.ts:
// One choice Claude offered: its words, and what choosing it leads to ('' when it says nothing more).
export type Choice = { label: string; detail: string }

// A question Claude asked with choices: one of AskUserQuestion's, or the question its answer ended on.
export type Ask = { question: string; header: string; choices: Choice[]; isMulti: boolean }

// What a running call is blocked on: the person answering a question or
// approving a plan.
export type Need = {
  kind: 'question' | 'plan'
  text: string
  // AskUserQuestion's questions with their choices (absent for a plan, and in older state).
  asks?: Ask[]
}

export type Job = {
  id: string
  tool: string
  detail: string
  startedAt: number
  endedAt: number | null
  isError: boolean
  agentId: string | null
  taskId: string | null
  need: Need | null
}

export type Task = {
  id: string
  subject: string
  status: 'pending' | 'in_progress' | 'completed'
}

export type Goal = { startedAt: number | null; tasks: Task[] }

export type AgentRow = {
  id: string
  label: string
  status: string
  parentId: string | null
  startedAt: number
  endedAt: number | null
}

// What a subagent is for, read off its spawn: which type was called, by whom,
// the role that type plays, the task it was given, what it is doing, what it said.
export type AgentCard = {
  id: string
  type: string
  name: string
  // The Agent call's few words.
  purpose: string
  // The prompt it was given, cut short.
  task: string
  // The agent type's own description: what that kind of agent is for.
  role: string
  // 'Claude', 'you', '<type> agent' for a nested spawn, a plugin's name, 'workflow'.
  calledBy: string
  model: string
  isBackground: boolean
  startedAt: number
  calls: number
  lastStep: string
  // Its final answer, cut short; '' until it ends.
  result: string
  endedAt: number | null
}

// A recurring prompt this session will run: a CronCreate job (/loop with an
// interval) or a self-paced /loop that books its next ScheduleWakeup each turn.
export type Loop = {
  id: string
  kind: 'cron' | 'wakeup'
  // The cron expression ('' for a self-paced loop).
  schedule: string
  // 'Every 5 minutes', 'Self-paced', 'Once'.
  every: string
  prompt: string
  recurring: boolean
  // null: it was running before this mod saw it made.
  startedAt: number | null
  nextAt: number | null
  lastFiredAt: number | null
  fires: number
  // A self-paced loop's last chosen delay and why.
  delaySeconds: number | null
  reason: string
  // A self-paced loop's pending wakeup, by its cron id, so it can be stopped.
  wakeId: string | null
  endedAt: number | null
}

// An agent type or a skill the launcher can start.
export type CatalogEntry = {
  kind: 'agent' | 'skill'
  name: string
  description: string
  source: string
  // What an agent file names: its model ('sonnet') and its colour ('blue').
  model?: string
  color?: string
}

export type Launch = {
  isOpen: boolean
  kind: 'agent' | 'skill'
  query: string
  // The entry chosen to run, by name; its task box shows.
  picked: string | null
  note: string
  // Counts the picks: each pick's task box is a new field, so it opens empty (absent in older state).
  seq?: number
}

// The main loop: working or the person's turn, and what it waits on.
export type MainState = {
  isWorking: boolean
  since: number | null
  // The question Claude ended its last answer with, until the person replies.
  reply: string | null
  // That question with the choices it offered (absent in older state).
  replyAsk?: Ask | null
  // What the engine says the session waits on (a permission prompt, a dialog).
  waiting: string | null
  waitingAt: number | null
}

// A subagent opened from the list: its task and its latest steps.
export type PeekLine = { kind: 'text' | 'running' | 'done' | 'failed'; text: string }

export type Peek = { agentId: string | null; task: string; lines: PeekLine[]; error: string }

// Sessions by what they ask of the person: blocked on them, working, or neither.
export type SessionGroup = 'needs' | 'working' | 'idle'

// Another Claude session on this computer: from the engine's registry, or the sessions mod when it is loaded.
export type SessionRow = {
  sessionId: string
  // A background session's id, what `claude attach` takes; null for one in a terminal.
  jobId: string | null
  name: string
  cwd: string
  pid: number | null
  // The terminal device it runs on (`/dev/ttys001`), found from its pid.
  tty: string | null
  // The engine's own word: busy, idle, waiting (terminal); working, blocked, done, failed, stopped (background).
  state: string
  group: SessionGroup
  since: number
  summary: string
  isSelf: boolean
  usage: { contextPercent: number | null; costUsd: number | null } | null
}

export type HubState = 'working' | 'idle' | 'needs'

// One Claude session working in this repository, as its own Ringside publishes it.
export type HubMember = {
  sessionId: string
  name: string
  branch: string
  state: HubState
  doing: string
  loops: number
  nextLoopAt: number | null
  agents: number
  at: number
  isSelf: boolean
  // Seen in the session list only: it does not run Ringside, so it cannot read the board.
  isBare: boolean
}

export type HubMessage = {
  id: string
  at: number
  fromId: string
  fromName: string
  by: 'person' | 'claude'
  // 'all', or one session's id.
  to: string
  text: string
}

// The repo hub: every session in this git repository and their shared board.
export type Hub = {
  root: string
  label: string
  branch: string
  members: HubMember[]
  messages: HubMessage[]
  // Who a post goes to: 'all' or a session id.
  to: string
  // Also wake the recipients' Claude with the post (as a message to that session).
  wake: boolean
  note: string
}


// ---- Ringside ----

export type NodeStatus = 'running' | 'waiting' | 'stuck' | 'idle' | 'done' | 'failed'
export type NodeKind = 'agent' | 'job' | 'loop' | 'workflow'
export type Progress = { done: number; total: number; note: string }

// One thing a session started: a subagent, a background shell, a loop, a workflow agent.
export type MapNode = {
  id: string
  kind: NodeKind
  // "Explore · find where agents are read"
  title: string
  status: NodeStatus
  // What it is doing, in plain words ("reading agents.ts"); the tool line is `raw`.
  now: string
  raw: string
  // What it waits on, why it may be stuck, or what it answered.
  why: string
  from: number
  to: number | null
  progress: Progress | null
  costUsd: number | null
  tokens: number | null
}

// What another session running this mod publishes about itself, as far as the map needs.
export type FleetFile = {
  sessionId: string
  name: string
  cwd: string
  branch: string
  state: HubState
  doing: string
  // Why it may be stuck; '' when it looks fine.
  stuck: string
  heartbeatAt: number
  nodes: MapNode[]
  // What it waits on the person for: 'ask' blocks it (a question, a plan), 'reply' is
  // the question its answer ended on; absent when nothing, or in an older file.
  needKind?: NeedKind
  // That question's choices, for cards on the other maps.
  asks?: Ask[]
}

export type NeedKind = 'ask' | 'reply'

// The pane's own view: which tab, how dense, and what is opened below the map.
export type View = {
  tab: 'map' | 'tasks' | 'launch'
  zoom: 'auto' | 'cards' | 'lines' | 'dots'
  // 'session:<id>', 'node:<sessionId>:<nodeId>', or null; this session's subagents open through `peek`.
  sel: string | null
  // A stop pressed once, waiting for the second press.
  confirm: string | null
  // When the replay button was last pressed (absent in older state).
  replayAt?: number | null
  // What the last Jump did, shown in that session's card (absent in older state).
  jump?: JumpNote | null
  // Cards picked for a question of Claude's not sent yet: '<call id>:<question index>' to labels.
  picks?: Record<string, string[]>
}

export type JumpNote = { sessionId: string; at: number; isOk: boolean; text: string }

declare module 'claude-code' {
  interface PluginState {
    'ringside': {
      jobs: Job[]
      goal: Goal
      agents: AgentRow[]
      cards: AgentCard[]
      loops: Loop[]
      catalog: CatalogEntry[]
      launch: Launch
      hub: Hub
      main: MainState
      peek: Peek
      cwd: string
      // Claude's own folder: CLAUDE_CONFIG_DIR, else ~/.claude.
      claudeDir: string
      // Every Claude session on this computer, read from the engine's registry (used when the sessions mod is not loaded).
      sessions: SessionRow[]
      // The pane is placed and is the one shown (not a tab behind another), for other mods
      // that keep their own band quiet while the map is on screen.
      isShown: boolean
      // Every session on this computer that runs this mod, from their board files.
      fleet: FleetFile[]
      view: View
    }
  }
}
